from collections import deque

def solve(n):
    queue = deque()
    for _ in range(n):
        queue.appendleft(0)
    for _ in range(3):
        queue.append(0)
    queue.appendleft(0)
    while queue:
        l = queue.popleft()
        r = queue.popleft()
        if l == n - 1 and r == n - 1:
            return 0
        if l + 2 < r:
            queue.append(l + 2)
        if l - 2 > -1:
            queue.append(l - 2)
        if r + 2 > l:
            queue.append(r + 2)
        if l + 1 > r:
            queue.append(l + 1)
        if l - 1 > r:
            queue.append(l - 1)
    return -1

